import subprocess, json

def echo(x):
    r = subprocess.run(["curl", "-s", f"http://127.0.0.1:8971/echo?x={x}"], capture_output=True, text=True)
    return json.loads(r.stdout)['y']

def shift(c, n):
    if 'a' <= c <= 'z':
        return chr((ord(c) - ord('a') + n) % 26 + ord('a'))
    if 'A' <= c <= 'Z':
        return chr((ord(c) - ord('A') + n) % 26 + ord('A'))
    if '0' <= c <= '9':
        return chr((ord(c) - ord('0') + n) % 10 + ord('0'))
    return c

# Let's try to figure out the transform
# Test: maybe it's shift by position (0-indexed)?
for s in ["abc", "abcd", "abcde", "hello", "brontide"]:
    out = echo(s)
    # Try: shift each char by its position
    shifted = ''.join(shift(c, i) for i, c in enumerate(s))
    # Try: shift each char by reverse position
    shifted_rev = ''.join(shift(c, len(s)-1-i) for i, c in enumerate(s))
    # Try: reverse then shift by position
    rev = s[::-1]
    rev_shifted = ''.join(shift(c, i) for i, c in enumerate(rev))
    # Try: shift by position then reverse
    shifted_then_rev = ''.join(shift(c, i) for i, c in enumerate(s))[::-1]

    print(f"{s!r} -> {out!r}")
    print(f"  shift-by-pos: {shifted!r}")
    print(f"  shift-by-revpos: {shifted_rev!r}")
    print(f"  rev+shift-by-pos: {rev_shifted!r}")
    print(f"  shift-by-pos+rev: {shifted_then_rev!r}")
EOF"}

